def interleaved_prompts(families: int, requests_per_family: int, blocks: int) -> list[dict[str, str]]:
    prefixes = [stable_prefix(f"family-{index}", blocks) for index in range(families)]
    prompts = []
    for request_index in range(requests_per_family):
        for family_index, prefix in enumerate(prefixes):
            prompts.append(
                {
                    "family": f"family-{family_index}",
                    "prompt": (
                        f"{prefix}\nUnique task {request_index}: inspect module_"
                        f"{request_index % 37}.rs and return its invariant only."
                    ),
                }
            )
    return prompts

assertion.region:
fn measured_tasks_interleave_families_and_keep_their_cacheable_prefixes() {
    let prompts = interleaved(2, 3, 2).unwrap();
    assert_eq!(
        prompts
            .iter()
            .map(|p| p.family.as_str())
            .collect::<Vec<_>>(),
        [
            "family-0", "family-1", "family-0", "family-1", "family-0", "family-1"
        ]
    );
    let prefix = stable_prefix("family-0", 2).unwrap();
    for (request, prompt) in prompts.iter().step_by(2).enumerate() {
        assert_eq!(
            prompt.prompt,
            format!(
                "{prefix}\nUnique task {request}: inspect module_{request}.rs and return its invariant only."
            )
        );
    }
    let seeded = interleaved(2, 1, 2).unwrap();
    assert_eq!(seeded[0].prompt, prompts[0].prompt);
    assert_eq!(seeded[1].prompt, prompts[1].prompt);
}

